import React, {useState} from "react";
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControl,
    FormHelperText,
    InputLabel,
    MenuItem,
    Select,
    TextField,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import {GridActionsCellItem, GridColDef, GridRowParams} from "@mui/x-data-grid";
import {toast} from "react-toastify";
import {AuthUser, UpsertUser, UserRole} from "../../models/auth";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
} from "../../ui/commonStyled/commonStyled";
import CoreButton from "../../ui/buttons/coreButton";
import Loader from "../../ui/loader/loader";
import {getApiErrorMessage} from "../../api/errors";
import {
    useCreateUserMutation,
    useDeleteUserMutation,
    useGetRolesQuery,
    useGetUsersQuery,
    useUpdateUserMutation,
} from "./usersApi";
import {useAuth} from "../../auth/AuthContext";

const roleLabels: Record<UserRole, string> = {
    employee: "Сотрудник",
    company_admin: "Администратор компании",
    super_admin: "Администратор системы",
};

const emptyDraft: UpsertUser = {
    name: "",
    email: "",
    role: "employee",
    password: "",
};

const UsersManagement = () => {
    const {user: currentUser} = useAuth();
    const {data: users = [], isLoading} = useGetUsersQuery();
    const {data: roles = ["employee", "company_admin"]} = useGetRolesQuery();
    const [createUser, {isLoading: isCreating}] = useCreateUserMutation();
    const [updateUser, {isLoading: isUpdating}] = useUpdateUserMutation();
    const [deleteUser] = useDeleteUserMutation();
    const [editingUser, setEditingUser] = useState<AuthUser | null>(null);
    const [draft, setDraft] = useState<UpsertUser>(emptyDraft);
    const [dialogOpen, setDialogOpen] = useState(false);

    const openCreate = () => {
        setEditingUser(null);
        setDraft(emptyDraft);
        setDialogOpen(true);
    };

    const openEdit = (user: AuthUser) => {
        setEditingUser(user);
        setDraft({name: user.name, email: user.email, role: user.role, password: ""});
        setDialogOpen(true);
    };

    const save = async () => {
        try {
            if (editingUser) {
                await updateUser({id: editingUser.id, body: draft}).unwrap();
            } else {
                await createUser(draft).unwrap();
            }
            toast.success(editingUser ? "Пользователь обновлён" : "Пользователь создан");
            setDialogOpen(false);
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось сохранить пользователя"));
        }
    };

    const remove = async (user: AuthUser) => {
        if (!window.confirm(`Удалить пользователя ${user.name}?`)) {
            return;
        }

        try {
            await deleteUser(user.id).unwrap();
            toast.success("Пользователь удалён");
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось удалить пользователя"));
        }
    };

    const columns: GridColDef<AuthUser>[] = [
        {field: "name", headerName: "Имя", minWidth: 180, flex: 1},
        {field: "email", headerName: "Email", minWidth: 230, flex: 1},
        {
            field: "role",
            headerName: "Роль",
            minWidth: 210,
            valueFormatter: (params) => roleLabels[params.value as UserRole] || params.value,
        },
        {
            field: "actions",
            type: "actions",
            width: 110,
            getActions: (params: GridRowParams<AuthUser>) => [
                <GridActionsCellItem
                    key="edit"
                    icon={<EditOutlinedIcon/>}
                    label="Редактировать"
                    onClick={() => openEdit(params.row)}
                />,
                <GridActionsCellItem
                    key="delete"
                    icon={<DeleteOutlineIcon/>}
                    label="Удалить"
                    disabled={params.row.id === currentUser?.id}
                    onClick={() => remove(params.row)}
                />,
            ],
        },
    ];

    if (isLoading) {
        return <Loader/>;
    }

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>Пользователи компании</PageTitle>
                    <PageSubtitle>
                        Управление сотрудниками, администраторами и паролями в рамках активной компании.
                    </PageSubtitle>
                </PageTitleGroup>
                <CoreButton muiType="success" text="Добавить пользователя" leftIcon={<AddIcon/>} onClick={openCreate}/>
            </PageHeader>
            <Surface>
                <StyledDataGrid
                    autoHeight
                    rows={users}
                    columns={columns}
                    pageSizeOptions={[25, 50]}
                    disableRowSelectionOnClick
                />
            </Surface>

            <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} fullWidth maxWidth="sm">
                <DialogTitle>{editingUser ? "Редактирование пользователя" : "Новый пользователь"}</DialogTitle>
                <DialogContent sx={{display: "grid", gap: 2, paddingTop: "12px !important"}}>
                    <TextField
                        required
                        label="Имя"
                        value={draft.name}
                        onChange={(event) => setDraft({...draft, name: event.target.value})}
                    />
                    <TextField
                        required
                        type="email"
                        label="Email"
                        value={draft.email}
                        onChange={(event) => setDraft({...draft, email: event.target.value})}
                    />
                    <FormControl>
                        <InputLabel id="user-role-label">Роль</InputLabel>
                        <Select
                            labelId="user-role-label"
                            label="Роль"
                            value={draft.role}
                            onChange={(event) => setDraft({...draft, role: event.target.value as UserRole})}
                        >
                            {roles.filter(role => role !== "super_admin").map((role) => (
                                <MenuItem key={role} value={role}>{roleLabels[role]}</MenuItem>
                            ))}
                        </Select>
                        <FormHelperText>{draft.role === "company_admin"
                            ? "Полное управление своей компанией, сотрудниками и заказами. Подключение бота и системные настройки выполняет глобальный администратор."
                            : "Работа с заказами и данными своей компании."}</FormHelperText>
                    </FormControl>
                    <TextField
                        required={!editingUser}
                        type="password"
                        label={editingUser ? "Новый пароль (необязательно)" : "Пароль"}
                        value={draft.password}
                        onChange={(event) => setDraft({...draft, password: event.target.value})}
                        helperText="Не менее 8 символов"
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setDialogOpen(false)}>Отмена</Button>
                    <Button
                        variant="contained"
                        onClick={save}
                        disabled={isCreating || isUpdating || !draft.name || !draft.email || (!editingUser && !draft.password)}
                    >
                        Сохранить
                    </Button>
                </DialogActions>
            </Dialog>
        </MainDiv>
    );
};

export default UsersManagement;
